INSERT OR REPLACE INTO District_Adjacencies (DistrictType,YieldChangeId)
SELECT			DistrictType,			'SFDH100_DIPLOMATIC_QUARTER_CULTURE'	FROM	Districts	WHERE	DistrictType IS 'DISTRICT_THEATER' 					OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_THEATER')
UNION SELECT	DistrictType,			'SFDH100_DIPLOMATIC_QUARTER_GOLD'		FROM	Districts	WHERE	DistrictType IS 'DISTRICT_COMMERCIAL_HUB' 			OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_COMMERCIAL_HUB')
UNION SELECT	DistrictType,			'SFDH100_DIPLOMATIC_QUARTER_GOLD'		FROM	Districts	WHERE	DistrictType IS 'DISTRICT_HARBOR' 					OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_HARBOR')
UNION SELECT	DistrictType,			'SFDH100_CITY_CENTER_TOKEN'				FROM	Districts	WHERE	DistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER' 		OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER')
UNION SELECT	DistrictType,			'SFDH100_CAMPUS_TOKEN'					FROM	Districts	WHERE	DistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER' 		OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER')
UNION SELECT	DistrictType,			'SFDH100_THEATER_TOKEN'					FROM	Districts	WHERE	DistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER' 		OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER')
UNION SELECT	DistrictType,			'SFDH100_GOVERNMENT_TOKEN'				FROM	Districts	WHERE	DistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER' 		OR DistrictType IN (SELECT CivUniqueDistrictType FROM DistrictReplaces WHERE ReplacesDistrictType IS 'DISTRICT_DIPLOMATIC_QUARTER');
